baseline_graph.command:
node --input-type=module <<'NODE'
import {readFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {runInNewContext} from 'node:vm';
import {build} from 'esbuild';
const sha=x=>createHash('sha256').update(x).digest('hex');
const dir='docs/remediation/evidence/W01.02/';
const manifest=JSON.parse(readFileSync(dir+'artifact-manifest-v3.json'));
const test=readFileSync('src/index.api-boundary.test.ts','utf8');
const context={JSON};
for(const name of ['SECRET','PRIVATE','CACHE_KEY','STORAGE_KEY','STATE_KEY'])context[name]=runInNewContext(test.match(new RegExp('const '+name+" = ('[^']*');"))[1]);
const wrapper=test.match(/const wrapper = (`[\s\S]*?`);\n\nlet runtime/);
const banner=test.match(/banner: \{ js: (`[\s\S]*?`) \},/);
const originalSources={};
const result=await build({stdin:{contents:runInNewContext(wrapper[1],context),resolveDir:process.cwd(),sourcefile:'w0102-runtime.ts',loader:'ts'},bundle:true,write:false,metafile:true,format:'esm',platform:'browser',target:'es2022',conditions:['workerd','worker','browser'],external:['cloudflare:*','node:*'],alias:{path:'node:path','node:os':'unenv/node/os'},banner:{js:runInNewContext(banner[1])},logLevel:'silent',plugins:[{name:'original',setup(b){b.onResolve({filter:/^(\.\/src\/index\.ts|@\/routes\/api)$/},a=>({path:a.path==='./src/index.ts'?'index':'api',namespace:'w0102-before'}));b.onLoad({filter:/.*/,namespace:'w0102-before'},a=>{const contents=readFileSync(dir+'before-'+a.path+'.ts.txt','utf8').slice(0,-1);originalSources[a.path]=sha(contents);return {contents,loader:'ts',resolveDir:process.cwd()};});}}]});
const inputs=Object.keys(result.metafile.inputs).sort();
const physical=inputs.filter(p=>p!=='w0102-runtime.ts'&&!p.startsWith('w0102-before:'));
const uncovered=physical.filter(p=>!manifest.files.some(f=>f.path===p)).map(path=>({path,sha256:sha(readFileSync(path))}));
const mismatches=physical.flatMap(path=>{const f=manifest.files.find(f=>f.path===path);return f&&sha(readFileSync(path))!==f.sha256?[path]:[];});
console.log(JSON.stringify({at:new Date().toISOString(),inputCount:inputs.length,physicalInputs:physical.length,inputPathsSha256:sha(JSON.stringify(inputs)),bundleSha256:sha(result.outputFiles[0].contents),uncovered,mismatches,originalSources},null,2));
NODE
